chapter(1, 'Arrivals and check-in on the phone', 'Check in an arriving guest from the phone: the guided steps, the ID and the purpose of visit.', 'Aarav (Reception)', 'reception', menu='Arrivals', display='mobile')
click('btn:Arrivals', 'Tap the Arrivals tab.', 'Arrivals lists everyone expected today.', expect='The arrivals open.', check="ctx.page==='arrivals'")
read('Each arrival is a card with the room, the dates, the registration state and the room state. Ishaan Bose, room 103, is not registered yet. Walk-in at the bottom starts a guest without a booking.', 'The card tells you at once if the room is ready.', target='sel:main', expect='The arrival cards.')
click('btn:Ishaan Bose', 'Tap the card of Ishaan Bose.', 'Tapping an arrival opens the guided check-in directly, with the same six steps as on the PC.', expect='The guided check-in opens at Step 2 of 6, Verify guest.', check="has('Verify guest')")
step('Type the address 14 Gokhale Road, Pune 411004, choose the ID type Aadhaar and type the fictional number 234510094321.', 'The ID is checked and shown masked afterwards.', target='field:ID number', auto=['type:field:Address|14 Gokhale Road, Pune 411004', 'select:field:ID type|Aadhaar', 'type:field:ID number|234510094321'], action='type', expect='Address and ID filled.')
click('modalbtn:Verify guest', 'Tap Verify guest.', 'The registration is saved and the guest is Verified.', expect='Step 3 of 6, Room, opens.', check="has('Step 3 of 6')")
click('modalbtn:Next', 'Room 103 is ready. Tap Next.', 'A room that is not ready cannot be given.', expect='Step 4 of 6, Tariff, opens.', check="has('Step 4 of 6')")
tick('field:The guest has confirmed', 'Tick that the guest confirmed the tariff.', 'Rate disputes are avoided when the guest agreed at check-in.', expect='The tariff is confirmed.')
click('modalbtn:Next', 'Tap Next.', 'Next is the advance, which is optional.', expect='Step 5 of 6, Advance, opens.', check="has('Step 5 of 6')")
click('modalbtn:Next', 'No advance this time. Tap Next.', 'An advance can be taken later from the folio.', expect='The Check in step opens.', check="has('Step 6 of 6')")
pick('field:Purpose of visit', 'Tourism', 'Choose the purpose of visit Tourism.', 'The purpose of visit is part of the legal guest record.', expect='Purpose chosen.')
click('modalbtn:Check in', 'Tap Check in.', 'The guest is in house and room 103 shows Occupied.', expect='Ishaan Bose is checked in.', msgText='Checked in to room 103. Room board updated.', check="has('Checked in')")
press('Escape', 'Close the sheet.', 'You return to the arrivals.', target='sel:main', expect='The arrivals are shown.')
